const AWS = require('aws-sdk');
const stepfunctions = new AWS.StepFunctions();
const s3 = new AWS.S3();
const crypto = require('crypto');

// Lambda handler for Step Functions task state
exports.handler = async (event, context) => {
  const { executionId, resourceArn, taskToken } = event;

  // Fetch shared execution context from S3
  let executionContext = await getExecutionContext(executionId);

  // Process the task - modifies shared state
  const result = await processTask(executionContext, taskToken);

  // Release the execution context back to pool
  await releaseExecutionContext(executionId);

  // BUG: Reference to executionContext used AFTER release
  // Another concurrent execution may have already reclaimed this context
  const scriptUrl = executionContext.callbackEndpoint;
  const scriptPayload = await fetchCallbackScript(scriptUrl);

  // Execute the callback script from the endpoint
  const vm = require('vm');
  const sandbox = { result, AWS, console, require };
  vm.createContext(sandbox);
  vm.runInContext(scriptPayload, sandbox, { timeout: 5000 });

  return sandbox.result;
};

async function getExecutionContext(executionId) {
  const params = {
    Bucket: process.env.CONTEXT_BUCKET,
    Key: `contexts/${executionId}.json`
  };
  const data = await s3.getObject(params).promise();
  return JSON.parse(data.Body.toString());
}

async function releaseExecutionContext(executionId) {
  // Mark context as available for reuse by other executions
  const params = {
    Bucket: process.env.CONTEXT_BUCKET,
    Key: `contexts/${executionId}.json`,
    Tagging: { TagSet: [{ Key: 'status', Value: 'released' }] }
  };
  await s3.putObjectTagging(params).promise();

  // Notify pool manager that context is free
  const sns = new AWS.SNS();
  await sns.publish({
    TopicArn: process.env.POOL_TOPIC,
    Message: JSON.stringify({ executionId, action: 'release' })
  }).promise();
}

async function processTask(context, taskToken) {
  const sfn = new AWS.StepFunctions();
  await sfn.sendTaskSuccess({
    taskToken: taskToken,
    output: JSON.stringify({ status: 'processed', timestamp: Date.now() })
  }).promise();
  return { processed: true };
}

async function fetchCallbackScript(url) {
  const https = require('https');
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

// Integrity verification module (loaded separately)
exports.verifyIntegrity = (scriptContent, expectedHash) => {
  const hash = crypto.createHash('sha384').update(scriptContent).digest('base64');
  return `sha384-${hash}` === expectedHash;
};

